create policy "Enable read for authenticated users only"
on "public"."brokers"
as permissive
for select
to authenticated
using (true);


create policy "Enable insert for authenticated users only"
on "public"."jobs"
as permissive
for insert
to authenticated
with check (true);


create policy "users can update own data"
on "public"."jobs"
as permissive
for update
to public
using ((auth.uid() = "user"));


create policy "users can view own data"
on "public"."jobs"
as permissive
for select
to public
using ((auth.uid() = "user"));




